// Generated by toolbox — the shader's ramp / curve lookup tables.
// Do not edit by hand: change the SkSL Shader node and export again.

import { AlphaType, ColorType, Skia } from "react-native-skia";

// A 256×1 lookup table (RGBA8, unpremultiplied sRGB): exactly the bytes
// toolbox sampled in the preview.
function makeLut(base64: string) {
  const image = Skia.Image.MakeImage(
    { width: 256, height: 1, alphaType: AlphaType.Unpremul, colorType: ColorType.RGBA_8888 },
    Skia.Data.fromBase64(base64),
    256 * 4
  );
  if (!image) throw new Error("toolbox export: could not build a lookup-table image");
  return image;
}

// ramp channel "ink" (256×1 lookup table)
export const LUT_ink = makeLut("");

// curve channel "lift" (256×1 lookup table)
export const LUT_lift = makeLut("");
